import {VIEW,VESSEL,LANCE,currentAt,clamp,condition,progress} from './model.js';
export function vesselMarkup(){return `<svg id="vessel" viewBox="${VIEW.x} ${VIEW.y} ${VIEW.width} ${VIEW.height}" role="img" aria-label="Move the mouse to position the liquid lance. Left-click once to fire a high-pressure liquid pulse.">
<defs><linearGradient id="bb-metal" x2="0" y2="1"><stop stop-color="#a6b9b3"/><stop offset=".18" stop-color="#52696b"/><stop offset=".52" stop-color="#233a42"/><stop offset="1" stop-color="#a7bcb4"/></linearGradient><linearGradient id="bb-liquid" x2="0" y2="1"><stop stop-color="#214c59"/><stop offset=".4" stop-color="#123d50"/><stop offset="1" stop-color="#082a40"/></linearGradient><radialGradient id="bb-toxic" cx=".35" cy=".28"><stop stop-color="#e8eeaa" stop-opacity=".82"/><stop offset=".5" stop-color="#bcd44e" stop-opacity=".47"/><stop offset="1" stop-color="#7e9d32" stop-opacity=".8"/></radialGradient><filter id="bb-glow" x="-100%" y="-100%" width="300%" height="300%"><feGaussianBlur stdDeviation="5"/></filter><clipPath id="bb-water"><rect x="${VESSEL.left}" y="${VESSEL.top}" width="${VESSEL.right-VESSEL.left}" height="${VESSEL.bottom-VESSEL.top}"/></clipPath><pattern id="bb-mesh" width="26" height="24" patternUnits="userSpaceOnUse"><path d="M0 12h26M13 0v24" stroke="#8ba9a1" stroke-opacity=".045"/></pattern></defs>
<g id="housing" pointer-events="none">
<path d="M25 119Q25 73 70 73H1130Q1175 73 1175 119V640Q1175 688 1130 688H70Q25 688 25 640Z" fill="#152832" stroke="url(#bb-metal)" stroke-width="18"/>
<rect x="43" y="87" width="1114" height="574" rx="7" fill="url(#bb-liquid)" stroke="#98b9ad" stroke-width="3"/>
<rect id="liquid-opening" x="50" y="94" width="1100" height="560" fill="url(#bb-mesh)"/><path d="M50 94H1150" stroke="#9dcab9" stroke-width="4" opacity=".55"/>
<path d="M1150 94H1188V66H1160" fill="none" stroke="#10222b" stroke-width="30"/><path d="M1150 94H1188V66H1160" fill="none" stroke="url(#bb-metal)" stroke-width="18"/><text x="1204" y="36" text-anchor="end" class="machine-label outlet-label">UNTREATED</text><text x="1204" y="52" text-anchor="end" class="machine-label outlet-label">OUTLET ↑</text>
<path d="M60 645H1140" stroke="#182c34" stroke-width="16"/><path d="M60 645H1140" stroke="#718983" stroke-width="6"/>
${[100,260,430,600,770,940,1100].map(x=>`<path d="M${x} 645v-10" stroke="#a9b7a1" stroke-width="5"/>`).join('')}
<text x="60" y="679" class="machine-label">HIGH-PRESSURE LIQUID INJECTION</text><text x="1140" y="679" text-anchor="end" class="machine-label">SEALED VESSEL</text>
${[16,1184].flatMap(x=>[124,290,465,640].map(y=>`<circle cx="${x}" cy="${y}" r="6" fill="#b3c5b9"/><path d="M${x-3} ${y+2}l6-4" stroke="#283c42" stroke-width="2"/>`)).join('')}
<path d="M10 350V590Q10 615 25 615M1175 590H1190V350H1175" fill="none" stroke="#415e61" stroke-width="10"/>
<circle id="effective-lamp" cx="37" cy="709" r="6" fill="#d5b477"/><text x="55" y="713" class="machine-label" id="machine-state">MANUAL RECOVERY REQUIRED</text>
</g>
<g id="eyeline" pointer-events="none" aria-live="polite" transform="translate(0 -136)">
<rect x="374" y="112" width="452" height="101" rx="9" fill="#142c2c" stroke="#76918a"/>
<g id="counter-live"><text id="counter-label" x="600" y="133" text-anchor="middle" class="counter-label">CONTAMINATED POCKETS REMAINING</text><text id="remaining" x="600" y="178" text-anchor="middle" class="counter-number">16</text><text x="600" y="200" text-anchor="middle" class="counter-treated">TREATED: <tspan id="treated">0 / 16</tspan></text></g>
<g id="counter-success"><text x="600" y="141" text-anchor="middle" class="success-title">SCRUBBER EFFECTIVE</text><text x="600" y="165" text-anchor="middle" class="counter-label">AUTOMATIC TREATMENT RESTORED</text><text x="600" y="193" text-anchor="middle" class="success-leave">YOU CAN LEAVE</text></g>
</g>
<g id="currents" pointer-events="none" clip-path="url(#bb-water)"></g><g id="wake" pointer-events="none" clip-path="url(#bb-water)"></g><g id="jet-column" pointer-events="none" clip-path="url(#bb-water)"></g><g id="gas" pointer-events="none" clip-path="url(#bb-water)"></g>
<g id="lance-assembly" pointer-events="none"><path d="M60 625H1140" stroke="#091d25" stroke-width="12"/><path d="M60 625H1140" stroke="url(#bb-metal)" stroke-width="6"/>
<g id="jet-guide"></g><path id="supply-line" fill="none" stroke="#152e37" stroke-width="10"/><path id="supply-braid" fill="none" stroke="#729b9f" stroke-width="4" stroke-dasharray="3 3"/>
<g id="lance-carriage"><g transform="translate(0 610) scale(.88) translate(0 -610)"><rect x="-62" y="632" width="124" height="32" rx="6" fill="url(#bb-metal)" stroke="#b8c7b5" stroke-width="3"/><rect x="-52" y="639" width="104" height="17" rx="4" fill="#263e3e"/><path d="M-43 641h86M-43 653h86" stroke="#c2b17c" stroke-width="2"/><circle cx="-44" cy="647" r="5" fill="#0c2026"/><circle cx="44" cy="647" r="5" fill="#0c2026"/><path d="M-18 632V623L-9 614V610H9V614L18 623V632" fill="url(#bb-metal)" stroke="#bad8d4" stroke-width="2"/><rect x="24" y="626" width="27" height="17" rx="3" fill="#344a52" stroke="#d2b06f"/><circle id="valve-lamp" cx="38" cy="634" r="4" fill="#b5dbab"/></g><path d="M-9 610H9" stroke="#b4f5fa" stroke-width="4"/></g><path id="command-marker" fill="none" stroke="#e2c583" stroke-width="2"/>
</g><g id="splash" pointer-events="none"></g>

</svg>`;}
function pocketPath(b,t){const points=[];const squeeze=b.deformation*.2;for(let i=0;i<14;i++){const a=i/14*Math.PI*2,wobble=1+.045*Math.sin(a*3+t*3+b.phase)+.025*Math.sin(a*5-t*2+b.phase);points.push({x:b.x+Math.cos(a)*b.r*wobble*(1+squeeze),y:b.y+Math.sin(a)*b.r*wobble*(1-squeeze)});}let d='';for(let i=0;i<points.length;i++){const a=points[i],b=points[(i+1)%points.length],m={x:(a.x+b.x)/2,y:(a.y+b.y)/2};d+=i===0?`M${m.x} ${m.y}`:'';const c=points[(i+2)%points.length],n={x:(b.x+c.x)/2,y:(b.y+c.y)/2};d+=`Q${b.x} ${b.y} ${n.x} ${n.y}`;}return d+'Z';}
export function createRenderer(container){container.innerHTML=vesselMarkup();const svg=container.querySelector('svg'),get=id=>svg.querySelector('#'+id),set=(id,k,v)=>get(id).setAttribute(k,v);
 return {svg,render(s){const p=progress(s);get('counter-label').textContent=s.time-s.lastPenalty<.9?'CHEMICAL BREAKTHROUGH · +1 TO TREAT':'CONTAMINATED POCKETS REMAINING';get('remaining').textContent=p.remaining;get('treated').textContent=`${p.treated} / ${p.total}`;const t=s.time,q=s.pulse,active=q.phase!=='READY',x=active?q.origin:s.carriage.x,recoil=q.phase==='PROPAGATING'?Math.sin(clamp((t-q.start)/.08,0,1)*Math.PI)*4:0;
 svg.dataset.phase=q.phase;svg.dataset.restored=String(s.phase==='AUTO');svg.dataset.penalty=String(t-s.lastPenalty<.9);set('eyeline','data-flash',t-s.lastPenalty<.9?'true':'false');set('eyeline','data-event',s.lastPenaltyEvent?.serial??0);set('lance-carriage','transform',`translate(${s.carriage.x} ${recoil})`);
 const width=active?q.width:s.config.width,reach=active?q.reach:s.config.reach;
 set('supply-line','d',`M60 645C170 655 ${x-110} 655 ${x-40} 650`);set('supply-braid','d',`M60 645C170 655 ${x-110} 655 ${x-40} 650`);
 set('valve-lamp','fill',q.phase==='READY'?'#bde5a8':q.phase==='PROPAGATING'?'#e2fcff':'#cfa578');
 get('jet-guide').innerHTML=`<path d="M${x} ${LANCE.base-5}V${LANCE.base-reach}" stroke="#b4e4e7" stroke-dasharray="5 9" opacity=".17"/><path d="M${x-width/2} ${LANCE.base-reach}h${width}" stroke="#badce1" opacity=".45"/>`;
 // Front and upward-moving tail are model state. The column fades; it never
 // retracts as a rigid object or creates a second hidden collision region.
 let liquid='';if(q.opacity>0&&active){const length=Math.max(0,q.tail-q.front),alpha=q.opacity;
 liquid=`<path d="M${x} ${q.tail}V${q.front}" stroke="#62e2f5" stroke-width="${width}" opacity="${alpha*.14}"/><path d="M${x-width/2} ${q.front}h${width}" stroke="#e0ffff" stroke-width="2" opacity="${alpha}"/>`;
 for(let j=0;j<3;j++){let d='';for(let i=0;i<=12;i++){const y=q.tail-length*i/12,px=x+(j-1)*width*.23+Math.sin(y*.12-t*43+j*2)*width*.09;d+=`${i?'L':'M'}${px} ${y}`;}liquid+=`<path d="${d}" stroke="${j===1?'#e5ffff':'#73def3'}" stroke-width="${j===1?2:1.2}" fill="none" opacity="${alpha*(j===1?.85:.55)}"/>`;}
 for(let i=0;i<9;i++){const f=((t*4+i*.137)%1),y=q.tail-length*f,dx=Math.sin(i*2.7+t*31)*width*.42;liquid+=`<path d="M${x+dx} ${y}v${Math.min(8,Math.max(0,q.tail-y))}" stroke="#b4f4f8" stroke-width="1.5" opacity="${alpha*.5}"/>`;}}
 get('jet-column').innerHTML=liquid;
 get('currents').innerHTML=[140,370,600,830,1060].flatMap(cx=>[150,290,430,570].map(cy=>{let px=cx,py=cy,path=`M${px} ${py}`;for(let i=0;i<4;i++){const flow=currentAt(s,px,py);px+=flow.x*.28;py+=flow.y*.28;path+=`L${px} ${py}`;}return `<path d="${path}" fill="none" stroke="#8cc5c0" stroke-width="1.5" stroke-dasharray="8 12" stroke-dashoffset="${-t*10}" opacity=".13"/>`;})).join('');
 set('command-marker','d',`M${s.carriage.target-12} 673l12-8 12 8`);
 get('gas').innerHTML=s.pockets.map(b=>`<path d="${pocketPath(b,t)}" fill="url(#bb-toxic)" stroke="#d2e77c" stroke-width="2.5"/><path d="M${b.x-b.r*.6} ${b.y-b.r*.45}q${b.r*.4} ${-b.r*.45} ${b.r*.8} ${-b.r*.1}" stroke="#eff4bb" stroke-width="3" opacity=".6" fill="none"/>`).join('')+s.fragments.map(b=>{const dirty=clamp(b.mass/b.initial,0,1),r=b.r*(.8+.2*dirty);return `<ellipse cx="${b.x}" cy="${b.y}" rx="${r*(1+.06*Math.sin(t*6+b.phase))}" ry="${r*.9}" fill="${dirty>.25?'#bccd63':'#bbdfd6'}" fill-opacity="${.05+dirty*.27}" stroke="${dirty>.25?'#e0e99c':'#a2d9d8'}" stroke-opacity="${.17+dirty*.7}" stroke-width="1.5"/>`;}).join('');
 const pairs=new Map();for(const b of s.pockets)if(b.alreadySplit&&t-(b.splitAt??-10)<.20){const pair=pairs.get(b.jobId)??[];pair.push(b);pairs.set(b.jobId,pair);}
 for(const pair of pairs.values())if(pair.length===2){const [a,b]=pair,f=clamp(1-(t-a.splitAt)/.20,0,1);get('gas').innerHTML+=`<path d="M${a.x} ${a.y}Q${(a.x+b.x)/2} ${(a.y+b.y)/2-6*f} ${b.x} ${b.y}" fill="none" stroke="#c6d855" stroke-width="${Math.min(a.r,b.r)*f}" opacity="${f*.55}"/>`;}
 get('wake').innerHTML=s.wakes.map(w=>{const age=t-w.at,a=clamp(1-age/2.2,0,1),r=32+age*65,cx=w.x;return `<path d="M${cx-r} ${w.y-r*.8}q${r*2} ${-r*.5} ${r*2} ${r}t${-r} ${r}" stroke="#9ed4ce" stroke-width="2" opacity="${a*.2}" fill="none"/>`;}).join('');
 get('splash').innerHTML=s.effects.map(e=>{const age=t-e.at;
 if(e.type==='escape'){const a=clamp(1-age/1.8,0,1);return `<path d="M${e.x} ${VESSEL.top+1}Q${e.x+80} ${VESSEL.top-20-age*18} 1188 ${VESSEL.top-10}" fill="none" stroke="#b8d34e" stroke-width="${clamp(e.strength*24,e.penalty?18:1,35)}" opacity="${a*Math.min(1,e.penalty?Math.max(.8,e.strength):e.strength)*.8}" filter="url(#bb-glow)"/><circle cx="1188" cy="${VESSEL.top-25-age*22}" r="${10+age*10}" fill="#c8d66c" opacity="${a*Math.min(1,e.strength)*.45}"/>`;}
 if(e.type==='split'){const a=clamp(1-age/.75,0,1);return `<ellipse cx="${e.x}" cy="${e.y}" rx="${e.r*(1+age*.8)}" ry="${e.r*(.6-age*.3)}" fill="none" stroke="#cee15e" stroke-width="2" opacity="${a*.7}"/><text x="${e.x}" y="${e.y-e.r-14}" text-anchor="middle" class="machine-label" fill="#e8ec88" opacity="${a}">SPLIT — TWO UNTREATED POCKETS</text>`;}
 const a=clamp(1-age/.85,0,1),r=12+age*95*e.strength;return `<ellipse cx="${e.x}" cy="${e.y}" rx="${r}" ry="${r*.7}" fill="none" stroke="${e.type==='disperse'?'#e0f7cf':'#aec8b6'}" stroke-width="${e.type==='disperse'?4:2}" opacity="${a*.8}"/>${e.type==='disperse'?Array.from({length:8},(_,i)=>{const angle=i*Math.PI/4;return `<path d="M${e.x+Math.cos(angle)*r*.7} ${e.y+Math.sin(angle)*r*.7}l${Math.cos(angle)*13*a} ${Math.sin(angle)*13*a}" stroke="#e0f2d2" stroke-width="3" opacity="${a}"/>`;}).join(''):''}`;}).join('');
 set('effective-lamp','fill',s.phase==='AUTO'?'#cde59e':t-s.lastEscape<.9?'#e2a66c':'#b9b37a');get('machine-state').textContent=s.phase==='AUTO'?'AUTOMATIC TREATMENT ONLINE':'MANUAL RECOVERY REQUIRED';return condition(s);
 }};
}
